/**
 * Generates the JavaScript code to be injected into the NotebookLM console.
 * This script handles the DOM manipulation and timing logic.
 */
export const generateMacroScript = (prompts: string[], intervalMinutes: number = 1.5): string => {
  // Convert minutes to milliseconds
  const intervalMs = intervalMinutes * 60 * 1000;

  // Escape backticks and single quotes to prevent syntax errors in the generated string
  const serializedPrompts = JSON.stringify(prompts);

  return `
// ==========================================
// AutoMonitor: NotebookLM Automation Script
// ==========================================
(async function() {
  // 1. Setup Control Mechanism
  window.AUTO_MONITOR = { stopped: false };

  window.stopAutoMonitor = function() {
    window.AUTO_MONITOR.stopped = true;
    console.warn("%c 🛑 Stop command received. Terminating process...", "font-weight: bold; font-size: 14px;");
  };

  const prompts = ${serializedPrompts};
  const INTERVAL_MS = ${intervalMs};

  console.clear();
  console.log("%c 🤖 AutoMonitor Started ", "background: #0ea5e9; color: white; padding: 4px; border-radius: 4px; font-weight: bold;");
  console.log(\`%c Loaded \${prompts.length} prompts. Interval: ${intervalMinutes} minutes.\`, "color: #64748b");
  console.log("%c 💡 To STOP the script early, type stopAutoMonitor() and press Enter, or simply refresh the page.", "color: #e11d48; font-weight: bold;");

  // Helper: Sleep that checks for stop signal
  const sleep = (ms) => new Promise(resolve => {
    const start = Date.now();
    const check = () => {
      if (window.AUTO_MONITOR.stopped) return resolve(false); // Cancelled
      if (Date.now() - start >= ms) return resolve(true); // Done
      requestAnimationFrame(check);
    };
    check();
  });

  // Helper to find the input element
  const findInput = () => {
    const editable = document.querySelector('div[contenteditable="true"][role="textbox"]');
    if (editable) return editable;
    return document.querySelector('textarea');
  };

  // Helper to find the send button
  const findSendButton = () => {
    const buttons = Array.from(document.querySelectorAll('button'));
    return buttons.find(b => {
      const aria = b.getAttribute('aria-label');
      return aria === 'Send message' || aria === 'Submit';
    });
  };

  const simulateTyping = async (element, text) => {
    if (window.AUTO_MONITOR.stopped) return;
    element.focus();
    document.execCommand('insertText', false, text);
    element.dispatchEvent(new Event('input', { bubbles: true }));
    element.dispatchEvent(new Event('change', { bubbles: true }));
    await sleep(500);
  };

  for (let i = 0; i < prompts.length; i++) {
    if (window.AUTO_MONITOR.stopped) break;

    const prompt = prompts[i];
    console.log(\`%c [Step \${i + 1}/\${prompts.length}] Preparing to send...\`, "color: #0ea5e9; font-weight: bold;");

    const inputEl = findInput();
    if (!inputEl) {
      console.error("❌ Critical Error: Input field not found.");
      break;
    }

    // 1. Input the text
    await simulateTyping(inputEl, prompt);

    // Check stop before clicking
    if (window.AUTO_MONITOR.stopped) break;

    await sleep(1000);

    // 2. Click Send
    const sendBtn = findSendButton();
    if (sendBtn && !sendBtn.disabled) {
      sendBtn.click();
      console.log(\`%c ✅ Sent prompt \${i + 1}\`, "color: green");
    } else {
      console.warn("⚠️ Send button not found. Using Enter key fallback.");
      const enterEvent = new KeyboardEvent('keydown', {
        bubbles: true, cancelable: true, keyCode: 13, key: 'Enter'
      });
      inputEl.dispatchEvent(enterEvent);
    }

    // 3. Wait for interval (unless it's the last one)
    if (i < prompts.length - 1) {
      console.log(\`⏳ Waiting ${intervalMinutes} minutes before next prompt...\`);

      // Smart wait: check every second if we should stop
      let remaining = INTERVAL_MS;
      const tick = 1000;

      while (remaining > 0) {
         const shouldContinue = await sleep(tick);
         if (!shouldContinue || window.AUTO_MONITOR.stopped) {
            console.log("🛑 Timer cancelled.");
            break;
         }

         remaining -= tick;
         if (remaining > 0 && remaining % 30000 === 0) {
            console.log(\`... \${remaining / 1000}s remaining\`);
         }
      }
    }
  }

  if (window.AUTO_MONITOR.stopped) {
     console.log("%c 🛑 AutoMonitor Stopped by User ", "background: #e11d48; color: white; padding: 4px; border-radius: 4px;");
  } else {
     console.log("%c 🎉 All prompts executed successfully! ", "background: green; color: white; padding: 4px; border-radius: 4px;");
     alert("AutoMonitor: Workflow Complete!");
  }
})();
`;
};

