/**
 * Generates the JavaScript code to be injected into the NotebookLM console.
 * This script handles the DOM manipulation, timing logic, and response scraping.
 */
export const generateMacroScript = (prompts: string[], intervalMinutes: number = 1.5): string => {
  // Convert minutes to milliseconds
  const intervalMs = intervalMinutes * 60 * 1000;

  // Escape backticks and single quotes to prevent syntax errors in the generated string
  const serializedPrompts = JSON.stringify(prompts);

  return `
// ==========================================
// AutoMonitor: NotebookLM Automation Script
// ==========================================
(async function() {
  // --- STATE MANAGEMENT ---
  window.AUTO_MONITOR = { 
    stopped: false,
    transcript: [] 
  };

  window.stopAutoMonitor = function() {
    window.AUTO_MONITOR.stopped = true;
    console.warn("%c 🛑 Stop command received. Finalizing results...", "font-weight: bold; font-size: 14px;");
  };

  const prompts = ${serializedPrompts};
  const INTERVAL_MS = ${intervalMs};

  console.clear();
  console.log("%c 🤖 AutoMonitor Started ", "background: #0ea5e9; color: white; padding: 4px; border-radius: 4px; font-weight: bold;");
  console.log(\`%c Loaded \${prompts.length} prompts. Interval: ${intervalMinutes} minutes.\`, "color: #64748b");
  console.log("%c 💡 To STOP early and download what we have, type stopAutoMonitor() and press Enter.", "color: #e11d48; font-weight: bold;");

  // --- HELPERS ---

  const sleep = (ms) => new Promise(resolve => {
    const start = Date.now();
    const check = () => {
      if (window.AUTO_MONITOR.stopped) return resolve(false); // Cancelled
      if (Date.now() - start >= ms) return resolve(true); // Done
      requestAnimationFrame(check);
    };
    check();
  });

  const findInput = () => {
    const editable = document.querySelector('div[contenteditable="true"][role="textbox"]');
    if (editable) return editable;
    return document.querySelector('textarea');
  };

  const findSendButton = () => {
    const buttons = Array.from(document.querySelectorAll('button'));
    return buttons.find(b => {
      const aria = b.getAttribute('aria-label');
      return aria === 'Send message' || aria === 'Submit';
    });
  };

  /**
   * Tries to find the last AI response in the chat.
   * Heuristic: Look for the scrolling container, get the last child that contains text.
   */
  const getLastResponseText = () => {
    // Strategy 1: Look for common message containers in NotebookLM
    // NotebookLM often uses <mat-card> or specific classes, but they change.
    // We will target the main scrollable area and get the last textual element.

    // Attempt to find the main chat scroll container. 
    // Usually it's a large div in the middle of the screen.
    const scrollContainers = Array.from(document.querySelectorAll('div, main')).filter(el => {
       return el.scrollHeight > el.clientHeight && el.innerText.length > 200;
    });

    // Pick the deepest/most relevant container (usually the chat window)
    const chatContainer = scrollContainers.length > 0 ? scrollContainers[scrollContainers.length - 1] : document.body;

    if (!chatContainer) return "(Could not identify chat container)";

    // Get the last significant text node or element
    // We walk backwards from the end
    const walker = document.createTreeWalker(chatContainer, NodeFilter.SHOW_ELEMENT, null);
    let currentNode = walker.nextNode();
    let lastElement = null;
    while(currentNode) {
      lastElement = currentNode;
      currentNode = walker.nextNode();
    }

    // If we can find the list of messages, pick the last one.
    // Assuming the user message is followed by an AI response.
    // We'll capture the last 1000 chars of visible text as a fallback if structure is obscure.

    // Refined: Look for elements that might be messages.
    // Just grab the visible text of the last generic 'block' element.
    if (chatContainer.lastElementChild) {
       return chatContainer.lastElementChild.innerText;
    }

    return "(Response scraping failed - check console)";
  };

  const saveTranscript = () => {
    if (window.AUTO_MONITOR.transcript.length === 0) {
      console.warn("No transcript to save.");
      return;
    }

    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    let content = "# AutoMonitor Session Transcript\\n\\n";
    content += \`Date: \${new Date().toLocaleString()}\` + "\\n";
    content += \`Total Prompts: \${window.AUTO_MONITOR.transcript.length}\` + "\\n\\n";

    window.AUTO_MONITOR.transcript.forEach((item, idx) => {
      content += \`## Step \${idx + 1}: Prompt\` + "\\n";
      content += \`> \${item.prompt.replace(/\\n/g, '\\n> ')}\` + "\\n\\n";
      content += \`## Step \${idx + 1}: Answer\` + "\\n";
      content += \`\${item.response}\` + "\\n\\n";
      content += "---" + "\\n\\n";
    });

    const blob = new Blob([content], { type: 'text/markdown' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = \`notebooklm_transcript_\${timestamp}.md\`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    console.log("%c 💾 Transcript Downloaded! ", "color: green; font-weight: bold;");
  };

  const simulateTyping = async (element, text) => {
    if (window.AUTO_MONITOR.stopped) return;
    element.focus();
    document.execCommand('insertText', false, text);
    element.dispatchEvent(new Event('input', { bubbles: true }));
    await sleep(500);
  };

  // --- MAIN LOOP ---

  for (let i = 0; i < prompts.length; i++) {
    if (window.AUTO_MONITOR.stopped) break;

    const prompt = prompts[i];
    console.log(\`%c [Step \${i + 1}/\${prompts.length}] Processing...\`, "color: #0ea5e9; font-weight: bold;");

    const inputEl = findInput();
    if (!inputEl) {
      console.error("❌ Critical Error: Input field not found.");
      break;
    }

    // 1. Input the text
    await simulateTyping(inputEl, prompt);
    if (window.AUTO_MONITOR.stopped) break;

    await sleep(1000);

    // 2. Click Send
    const sendBtn = findSendButton();
    if (sendBtn && !sendBtn.disabled) {
      sendBtn.click();
      console.log(\`%c ⬆️ Sent prompt \${i + 1}\`, "color: #64748b");
    } else {
      console.warn("⚠️ Send button missing. Trying Enter.");
      const enterEvent = new KeyboardEvent('keydown', {
        bubbles: true, cancelable: true, keyCode: 13, key: 'Enter'
      });
      inputEl.dispatchEvent(enterEvent);
    }

    // 3. Wait for Interval (Time for AI to think and answer)
    console.log(\`⏳ Waiting ${intervalMinutes} minutes for response...\`);
    let remaining = INTERVAL_MS;
    const tick = 1000;

    let stoppedEarly = false;
    while (remaining > 0) {
       const shouldContinue = await sleep(tick);
       if (!shouldContinue || window.AUTO_MONITOR.stopped) {
          stoppedEarly = true;
          break;
       }
       remaining -= tick;
       if (remaining > 0 && remaining % 30000 === 0) {
          console.log(\`... \${remaining / 1000}s remaining\`);
       }
    }

    if (stoppedEarly) break;

    // 4. Scrape Response AFTER the wait
    // We assume the answer is now visible at the bottom of the chat.
    console.log("%c 🔍 Scraping response...", "color: #eab308");

    // Small buffer to ensure rendering
    await sleep(2000); 

    const responseText = getLastResponseText();

    // Store result
    window.AUTO_MONITOR.transcript.push({
      prompt: prompt,
      response: responseText
    });

    console.log(\`%c ✅ Captured Response \${i + 1} (\${responseText.length} chars)\`, "color: green");
  }

  // --- FINISH ---
  saveTranscript();

  if (window.AUTO_MONITOR.stopped) {
     console.log("%c 🛑 AutoMonitor Stopped. Partial results downloaded. ", "background: #e11d48; color: white; padding: 4px; border-radius: 4px;");
  } else {
     console.log("%c 🎉 Workflow Complete! Results downloaded. ", "background: green; color: white; padding: 4px; border-radius: 4px;");
     alert("AutoMonitor Complete! Your transcript is downloading.");
  }
})();
`;
};

