    if (parent) {
       const btns = Array.from(parent.querySelectorAll('button'));
       const validBtns = btns.filter(b => !b.disabled && b.getBoundingClientRect().width > 0);
       const sendBtn = validBtns.find(b => {
          const label = (b.getAttribute('aria-label') || '').toLowerCase();
          return label.includes('send') || label.includes('submit') || label.includes('发送');
       });
       if (sendBtn) return sendBtn;
       if (validBtns.length > 0) return validBtns[validBtns.length - 1];
    }
    return null;
  };

  const findChatScrollContainer = () => {
     const all = Array.from(document.querySelectorAll('div, main'));
     const scrollables = all.filter(el => {
        const style = window.getComputedStyle(el);
        const isScrollable = (el.scrollHeight > el.clientHeight) && 
                             (style.overflowY !== 'hidden');
        return isScrollable && el.clientHeight > 300 && el.clientWidth > 400;
     });
     if (scrollables.length === 0) return document.body;
     // Sort by text length is risky if empty. Sort by size is better.
     scrollables.sort((a, b) => (b.clientHeight * b.clientWidth) - (a.clientHeight * a.clientWidth));
     return scrollables[0];
  };

  // --- THE ELEGANT SNAPSHOT SCRAPER ---
  const getAddedContent = (container, startIndex, promptText) => {
      const children = Array.from(container.children);

      // Safety check: if list was cleared or refreshed, we can't slice
      if (children.length < startIndex) {
         console.warn("DOM Reset detected. Falling back to last child.");
         return children.length > 0 ? children[children.length - 1].innerText : "";
      }

      // 1. Get only the rows added AFTER we started this step
      // This physically excludes all previous history.
      const newRows = children.slice(startIndex);

      // 2. Join their text
      let fullText = newRows.map(r => r.innerText).join('\\n');

      // 3. Remove the prompt text (User Bubble)
      // Since 'newRows' contains [UserPrompt, AIResponse], we simply remove the user prompt string.
      if (fullText.includes(promptText)) {
          fullText = fullText.replace(promptText, '');
      } else {
          // Fuzzy fallback: remove first 50 chars if they look like prompt
          const snippet = promptText.substring(0, 30);
          if (fullText.includes(snippet)) {
             fullText = fullText.substring(fullText.indexOf(snippet) + snippet.length);
          }
      }

      return fullText.trim();
  };

  const saveTranscript = () => {
    if (window.AUTO_MONITOR.transcript.length === 0) {
      updateStatus('No answers captured to save.');
      return;
    }
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
    let content = "# NotebookLM Answers Export\\n\\n";
    content += \`Date: \${new Date().toLocaleString()}\` + "\\n";
    content += "---" + "\\n\\n";
    window.AUTO_MONITOR.transcript.forEach((item, idx) => {
      content += \`### Answer \${idx + 1}\` + "\\n\\n";
      content += item.response + "\\n\\n";
      content += "---" + "\\n\\n";
    });
