    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = \`notebooklm_answers_\${timestamp}.md\`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    console.log("%c 💾 Transcript Downloaded! ", "color: green; font-weight: bold;");
    updateStatus('File Downloaded!');
  };

  const simulateTyping = async (element, text) => {
    if (window.AUTO_MONITOR.stopped) return;
    element.focus();
    element.value = text; // Direct value set for some frameworks
    document.execCommand('insertText', false, text);
    element.dispatchEvent(new Event('input', { bubbles: true }));
    element.dispatchEvent(new Event('change', { bubbles: true }));
    await sleep(500);
  };

  // --- MAIN LOOP ---

  for (let i = 0; i < prompts.length; i++) {
    if (window.AUTO_MONITOR.stopped) break;

    const prompt = prompts[i];
    updateStatus(\`Step \${i + 1}/\${prompts.length}: Preparing...\`);

    try {
        // 1. DYNAMIC DOM RE-QUERY (Crucial for loop stability)
        // We find elements afresh every single time because React might have re-rendered them
        await sleep(1000); // Give UI a breather
        const chatInput = findChatInput();
        const scrollContainer = findChatScrollContainer();

        if (!chatInput) throw new Error("Input field not found");

        // 2. TAKE SNAPSHOT
        // We record 'how many items' are currently in the list.
        const childCountBefore = scrollContainer ? scrollContainer.children.length : 0;

        // 3. SEND
        updateStatus(\`Step \${i + 1}: Sending...\`);
        chatInput.style.border = "2px solid #0ea5e9"; // Visual cue
        await simulateTyping(chatInput, prompt);
        chatInput.style.border = "";

        const sendBtn = findSendButton(chatInput);
        if (sendBtn) {
            sendBtn.click();
        } else {
            chatInput.dispatchEvent(new KeyboardEvent('keydown', { bubbles: true, keyCode: 13, key: 'Enter' }));
        }

        // 4. WAIT
        updateStatus(\`Step \${i + 1}: Waiting ${intervalMinutes}m...\`);
        console.log(\`Step \${i+1}: Waiting...\`);

        let remaining = INTERVAL_MS;
        const tick = 1000;
        while (remaining > 0) {
            if (await sleep(tick) === false) break; // User stopped
            remaining -= tick;
            // Keep alive logic: scroll to bottom periodically to trigger lazy rendering
            if (remaining % 10000 === 0 && scrollContainer) {
                scrollContainer.scrollTop = scrollContainer.scrollHeight;
            }
        }
        if (window.AUTO_MONITOR.stopped) break;

        // 5. SCRAPE (Snapshot Diffing)
        updateStatus(\`Step \${i + 1}: Capturing...\`);
        // Force final scroll
        if (scrollContainer) scrollContainer.scrollTop = scrollContainer.scrollHeight;
        await sleep(2000); // Wait for render

        const answer = scrollContainer 
            ? getAddedContent(scrollContainer, childCountBefore, prompt) 
            : "Error: Container lost";

        window.AUTO_MONITOR.transcript.push({
            prompt: prompt,
            response: answer
        });

        console.log(\`✅ Captured Step \${i+1}\`);

    } catch (e) {
        console.error(\`❌ Error in Step \${i+1}: \`, e);
        updateStatus(\`Error in Step \${i+1}. Retrying next...\`);
        // We push a placeholder so the final MD file index matches the prompt index
        window.AUTO_MONITOR.transcript.push({
            prompt: prompt,
            response: \`(Error: Script failed at this step. Details: \${e.message})\`
        });
        await sleep(2000); // Wait before retrying
    }
  }

  saveTranscript();

  if (!window.AUTO_MONITOR.stopped) {
     updateStatus('Done! Downloading...');
     alert("AutoMonitor Finished! Transcript downloaded.");
  }
})();
`;
};

