          // Fallback: match first 40 chars
          const snippet = cleanPrompt.substring(0, 40);
          lastIndex = fullText.lastIndexOf(snippet);
          matchLength = snippet.length;
      }

      if (lastIndex === -1) return "Error: Could not locate prompt text in page to calculate answer.";

