     updateStatus(\`Step \${i+1}/\${prompts.length}: Inputting...\`);

     try {
         await sleep(1000);
         const inputEl = findChatInput();
         if (!inputEl) throw new Error("Input box not found");

         inputEl.focus();
         setNativeValue(inputEl, prompt);
         await sleep(800); // Slightly longer wait for UI to update

         const sendBtn = findSendButton(inputEl);
         if (sendBtn) {
             sendBtn.click();
