         }

         updateStatus(\`Step \${i+1}: Waiting for answer...\`);
         window.scrollTo(0, document.body.scrollHeight);

         const completed = await waitWithCountdown(INTERVAL_MS);
         if (!completed) break; 

         updateStatus(\`Step \${i+1}: Capturing...\`);
         await sleep(1500); 
         window.scrollTo(0, document.body.scrollHeight); 

         const answer = captureAnswerRobust(prompt);
         window.AUTO_MONITOR.transcript.push({ prompt, response: answer });
         console.log(\`✅ Step \${i+1} captured\`);

     } catch (e) {
         console.error(e);
         updateStatus(\`Error in step \${i+1}. Skipping...\`);
         window.AUTO_MONITOR.transcript.push({ prompt, response: \`Error: \${e.message}\` });
