          // We need to map this back to the original text roughly, but for now, 
          // let's just return the substring from the cleaned text, 
          // OR try to find it in the raw text.

          // Let's try to find the raw last line in the raw newTextSegment
          const rawIndex = newTextSegment.lastIndexOf(lastLine.trim());
          if (rawIndex !== -1) {
              return newTextSegment.substring(rawIndex + lastLine.trim().length).trim();
          }
          // If raw match fails (markdown formatting), fallback to returning the whole segment
          // but trying to strip the start.
          return newTextSegment.substring(newTextSegment.length / 2); // Very rough fallback
      }

