      const firstLine = promptLines[0] || promptText.substring(0, 20);
      const cleanFirstLine = cleanForMatching(firstLine);
      const indexByFirstLine = cleanNewText.lastIndexOf(cleanFirstLine);

      if (indexByFirstLine !== -1) {
          console.log("✅ Strategy 2 (First Line) matched.");
          const rawIndexFirst = newTextSegment.lastIndexOf(firstLine.trim());
          if (rawIndexFirst !== -1) {
              return newTextSegment.substring(rawIndexFirst + firstLine.trim().length).trim();
          }
      }

      // Strategy 3: Snapshot Diff (The "Whatever is new" approach)
      console.log("⚠️ Strategy 3 (Snapshot Diff) used. Answer might include prompt.");
      // If we can't find the prompt, we assume everything added after preStepTextLength is the interaction.
      // This will likely include the prompt text itself at the beginning, which is acceptable if we can't separate them.

      // Attempt to strip prompt by length heuristic
      if (newTextSegment.length > promptText.length) {
          // If the new text is significantly longer than the prompt, 
          // it's likely [Prompt] + [Answer]. 
          // We can return the end part.
          return newTextSegment;
      }

      return newTextSegment;
  };

  const saveTranscript = () => {
    if (window.AUTO_MONITOR.transcript.length === 0) {
      alert("No transcripts captured to save.");
      return;
    }
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, 19);
    let content = "# NotebookLM Answers Export\\n\\n";
    content += \`Date: \${new Date().toLocaleString()}\` + "\\n";
