         if (!completed) break; 

         updateStatus(\`Step \${i+1}: Capturing...\`);
         await sleep(1500); 
         window.scrollTo(0, document.body.scrollHeight); 

         const answer = captureAnswerRobust(prompt, preStepLength);

         // Validation: If answer is suspiciously short or error, flag it
         const finalAnswer = answer.length < 5 ? "(Content capture failed or answer was empty. Check console for details)" : answer;

         window.AUTO_MONITOR.transcript.push({ prompt, response: finalAnswer });
         console.log(\`✅ Step \${i+1} captured (\${finalAnswer.length} chars)\`);

         // Update length for next iteration
         currentTextLength = (document.querySelector('main') || document.body).innerText.length;

